/**
 * Given a book ID and an RNK page number, calculate the corresponding Sözler page number.
 */
export function getSozlerPageFromRnk(bookId: string, rnkPage: number): number {
    const info = CROSS_EDITION_MAPS[bookId];
    if (!info || !info.anchors || info.anchors.length === 0) {
        return rnkPage; // Fallback: 1-to-1 if not mapped
    }

    if (rnkPage <= 1) return 1;
    if (rnkPage >= info.maxRnk) return info.maxSoz;

    const anchors = info.anchors;
    // Find enclosing anchors
    for (let i = 0; i < anchors.length - 1; i++) {
        const [r1, s1] = anchors[i];
        const [r2, s2] = anchors[i + 1];

        if (rnkPage === r1) return s1;
        if (rnkPage === r2) return s2;

        if (rnkPage > r1 && rnkPage < r2) {
            // Linear interpolation between the two nearest text anchors
            const ratio = (rnkPage - r1) / (r2 - r1);
            return Math.round(s1 + ratio * (s2 - s1));
        }
    }

    return info.maxSoz;
}

/**
 * Given a book ID and a Sözler page number, calculate the corresponding RNK page number.
 */
export function getRnkPageFromSozler(bookId: string, sozPage: number): number {
    const info = CROSS_EDITION_MAPS[bookId];
    if (!info || !info.anchors || info.anchors.length === 0) {
        return sozPage;
    }

    if (sozPage <= 1) return 1;
    if (sozPage >= info.maxSoz) return info.maxRnk;

    const anchors = info.anchors;
    for (let i = 0; i < anchors.length - 1; i++) {
        const [r1, s1] = anchors[i];
        const [r2, s2] = anchors[i + 1];

        if (sozPage === s1) return r1;
        if (sozPage === s2) return r2;

        if (sozPage > s1 && sozPage < s2) {
            const ratio = (sozPage - s1) / (s2 - s1);
            return Math.round(r1 + ratio * (r2 - r1));
        }
    }

    return info.maxRnk;
}

/**
 * Get total pages for RNK edition of a book
 */
export function getRnkBookTotalPages(bookId: string): number | null {
    return CROSS_EDITION_MAPS[bookId]?.maxRnk || null;
}
